        , useBooleanCombination_( useBooleanCombination )
        , searchPattern_( std::move( searchPattern ) )
    {
        std::transform( markedLines.cbegin(), markedLines.cend(), std::back_inserter( marks_ ),
                        []( const auto& m ) { return m.get(); } );
    }

