    def _reader_loop(self) -> None:
        try:
            while True:
                line = self._reader.readline()
                if not line:
                    break

                payload = json.loads(line)
                if "id" in payload:
                    request_id = int(payload["id"])
                    with self._response_condition:
                        self._pending[request_id] = payload
                        self._response_condition.notify_all()
                    continue

